use super::{host::*,model::*};use crate::section;use serde_json::{Value,json};use std::{cell::RefCell,rc::Rc};
pub fn entry(i:usize)->Value{json!({"id":format!("synthetic-{i}"),"revision":1,"enabled":true,"payload":{"kind":"replacement_rule","source":format!("Synthetic phrase {i}"),"replacement":format!("Synthetic replacement {i}")},"scope":{"kind":"global"},"provenance":"manual","createdAtMs":0,"updatedAtMs":0,"voiceCommand":null})}
pub fn snapshot()->Snapshot{Snapshot{revision:1,availability:"ready".into(),store_revision:1,records:(0..3).map(entry).collect(),total:3,offset:0,next:None,import_preview:None,bulk:None,notice:None}}
pub struct FixtureHost{pub state:RefCell<Snapshot>,pub actions:RefCell<Vec<Action>>}impl Default for FixtureHost{fn default()->Self{Self{state:RefCell::new(snapshot()),actions:RefCell::new(vec![])}}}struct Stop;impl Subscription for Stop{fn stop(&mut self){}}
impl SectionHost<Snapshot,Action> for FixtureHost{fn subscribe(&self,_:murmur_core::events::Consumer,_:u64,_:crate::workspace::Inbox<Snapshot>)->Box<dyn Subscription>{Box::new(Stop)}fn request(&self,r:Request,i:crate::workspace::Inbox<Snapshot>){if !r.lease.is_current(){return}let mut s=self.state.borrow_mut();s.bulk=None;s.import_preview=None;let mut problem=None;match &r.action{
Action::List{filter,offset}=>{s.offset=*offset;s.records=(0..3).map(entry).filter(|v|title(v).to_lowercase().contains(&filter.query.to_lowercase())&&filter.enabled.is_none_or(|e|v["enabled"]==e)&&filter.kind.as_ref().is_none_or(|k|v["payload"]["kind"]==*k)).collect();s.total=s.records.len();},
Action::Upsert(v)=>{if valid_draft(v).is_err(){problem=Some(Problem::Invalid)}else{let mut v=v.clone();v["id"]=v.get("id").cloned().unwrap_or(json!("synthetic-new"));v["revision"]=json!(v["expectedRevision"].as_u64().unwrap_or(0)+1);let id=v["id"].clone();s.records.retain(|p|p["id"]!=id);s.records.push(v);s.total=s.records.len();s.store_revision+=1;}},
Action::Enable{entry,enabled}=>{if let Some(v)=s.records.iter_mut().find(|v|v["id"]==entry["id"]&&v["revision"]==entry["revision"]){v["enabled"]=json!(enabled);v["revision"]=json!(v["revision"].as_u64().unwrap()+1);s.store_revision+=1}else{problem=Some(Problem::Conflict)}},
Action::Delete(v)=>{s.records.retain(|p|p["id"]!=v["id"]);s.total=s.records.len();s.store_revision+=1;},Action::DeleteAll(revision)=>{if *revision==s.store_revision{s.records.clear();s.total=0;s.store_revision+=1}else{problem=Some(Problem::Conflict)}},
Action::Collect{filter,action}=>{let mut b=Bulk::new(filter.clone(),s.store_revision,s.records.len()).unwrap();b.append(s.store_revision,s.records.len(),s.records.clone(),None).unwrap();if *action==BulkAction::Delete{s.bulk=Some(b)}else{for v in &mut s.records{v["enabled"]=json!(*action==BulkAction::Enable);}s.notice=Some("Matching records updated.".into());}},Action::Apply{bulk,action}=>{if bulk.revision!=s.store_revision{problem=Some(Problem::Conflict)}else{let ids:Vec<_>=bulk.entries.iter().map(|v|v["id"].clone()).collect();if *action==BulkAction::Delete{s.records.retain(|v|!ids.contains(&v["id"]));s.total=s.records.len();}s.store_revision+=1;}},Action::InspectImport=>s.import_preview=Some(json!({"token":"synthetic-import","new":2,"duplicates":1,"conflicts":0})),Action::Import{..}=>s.notice=Some("Knowledge imported.".into()),Action::Retry=>s.availability="ready".into(),Action::Export=>s.notice=Some("Knowledge exported.".into()),_=>()};s.revision+=1;self.actions.borrow_mut().push(r.action);section::reply(&i,r.ticket,problem.map_or_else(||Ok(s.clone()),Err));}}
pub fn host()->Rc<Host>{Rc::new(FixtureHost::default())}
